<template>
 <SellerLayout><div class="bm-seller-editor">
  <RouterLink class="bm-seller-editor-back" :to="back"><MarketIcon name="chevronLeft"/>Sản phẩm và tồn kho</RouterLink>
  <header class="bm-seller-page-header"><div><h1>{{ creating?'Tạo sản phẩm mới':product.name||'Chỉnh sửa sản phẩm' }}</h1><div class="bm-seller-editor-meta"><span v-if="!creating">#{{ id }}</span><span class="bm-seller-status" :data-state="product.status">{{ creating?'Bản nháp mới':productStatusLabels[product.status]||'Đang tải' }}</span><span v-if="lastSaved" role="status">Đã lưu lúc {{ time(lastSaved) }}</span><span v-else-if="product.updatedAt">Cập nhật {{ time(product.updatedAt) }}</span></div><p>{{ creating?'Bắt đầu với thông tin cơ bản. Tiếp tục thêm nội dung và hình ảnh ngay sau khi tạo bản nháp.':'Quản lý nội dung, hình ảnh, tồn kho và gửi duyệt trong một không gian.' }}</p></div><div class="bm-seller-editor-actions"><button v-if="!creating" class="button button-outline" type="button" :disabled="locked||dirty||!gallery||!content" @click="openPreview">Xem trước</button><button class="button button-primary" type="button" :disabled="!loaded||locked||conflict||stockEditing||(!creating&&!dirty)" @click="save"><MarketIcon name="check"/>{{ busy?'Đang lưu…':creating?'Tạo bản nháp':'Lưu bản nháp' }}</button></div></header>
  <p v-if="loading" class="bm-seller-loading" role="status">Đang tải sản phẩm và danh mục…</p>
  <div v-if="error" ref="errorSummary" class="bm-seller-alert" role="alert" tabindex="-1"><strong>Kiểm tra trước khi tiếp tục</strong><p>{{ error }}</p><ul v-if="Object.keys(fields).length"><li v-for="(message,key) in fields" :key="key"><a :href="'#bm-seller-'+fieldTarget(key)" @click.prevent="jump('bm-seller-'+fieldTarget(key))">{{ message }}</a></li></ul><button v-if="!loaded||conflict" class="button button-outline" :disabled="locked" @click="reload">Đối chiếu dữ liệu máy chủ</button></div>
  <p v-if="success" class="bm-seller-success" role="status">{{ success }}</p>
  <p class="bm-seller-save-indicator" role="status">{{ locked?'Đang xử lý, vui lòng chờ…':dirty?'Có thay đổi chưa lưu':loaded?'Các trường đã lưu được giữ trên máy chủ.':'' }}</p>
  <template v-if="loaded"><nav class="bm-seller-section-nav" aria-label="Các phần sản phẩm"><a v-for="section in sections" :key="section.id" :href="'#'+section.id" @click.prevent="jump(section.id)">{{ section.label }}</a><label class="bm-seller-mobile-section-picker" for="bm-seller-section-select">Chuyển đến phần<select id="bm-seller-section-select" v-model="selectedSection" @change="jump(selectedSection)"><option v-for="section in sections" :key="section.id" :value="section.id">{{ section.label }}</option></select></label></nav>
  <div class="bm-seller-editor-grid"><div class="bm-seller-editor-sections">
   <section id="bm-seller-basic" class="bm-seller-editor-section" tabindex="-1"><h2>Thông tin cơ bản</h2><p class="bm-seller-help">Các trường dưới đây là bắt buộc. Bản nháp chỉ hiển thị với người có quyền quản lý.</p>
    <form ref="basicForm" class="bm-seller-basic-form" @submit.prevent="save"><fieldset :disabled="locked||conflict"><label class="bm-seller-field-wide" for="bm-seller-name">Tên sản phẩm<input id="bm-seller-name" v-model="form.name" required maxlength="180" autocomplete="off" :aria-invalid="!!fields.name" :aria-describedby="fields.name?'bm-seller-name-error':'bm-seller-name-help'"/><small id="bm-seller-name-help">Tên rõ loại cây, chậu hoặc phụ kiện · {{ form.name.length }}/180</small><span v-if="fields.name" id="bm-seller-name-error" class="management-field-error">{{ fields.name }}</span></label>
     <label for="bm-seller-price">Giá bán (VND)<input id="bm-seller-price" v-model="form.price" type="number" inputmode="decimal" min="1" max="9999999999999.99" step="0.01" required :aria-invalid="!!fields.price" aria-describedby="bm-seller-price-help"/><small id="bm-seller-price-help" v-if="fields.price" class="management-field-error">{{ fields.price }}</small><small id="bm-seller-price-help" v-else>Giá cho một sản phẩm, tính bằng đồng.</small></label>
     <label for="bm-seller-category">Danh mục<select id="bm-seller-category" v-model="form.categoryId" required :disabled="!creating&&!['DRAFT','REJECTED'].includes(product.status)" :aria-invalid="!!fields.categoryId" aria-describedby="bm-seller-category-help"><option value="">Chọn danh mục</option><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select><small id="bm-seller-category-help">{{ fields.categoryId||'Chỉ đổi danh mục khi đang nháp hoặc bị từ chối; metadata đã lưu được giữ.' }}</small></label>
     <label v-if="creating" for="bm-seller-stock-initial">Tồn kho ban đầu<input id="bm-seller-stock-initial" v-model="form.stock" type="number" inputmode="numeric" min="0" max="1000000" step="1" required :aria-invalid="!!fields.stock" aria-describedby="bm-seller-stock-initial-help"/><small id="bm-seller-stock-initial-help">{{ fields.stock||'Số nguyên từ 0 đến 1.000.000. Có thể bổ sung trước khi gửi duyệt.' }}</small></label>
    </fieldset><p v-if="!creating&&['ACTIVE','PENDING'].includes(product.status)" class="bm-seller-help">Sửa tên hoặc giá sẽ đưa sản phẩm về bản nháp để duyệt lại. Đơn đã đặt giữ nguyên giá.</p><button type="submit" class="button button-outline" :disabled="locked||conflict||(!creating&&!basicDirty)">{{ creating?'Tạo bản nháp':'Lưu thông tin cơ bản' }}</button></form>
   </section>
   <section id="bm-seller-content" class="bm-seller-editor-section" tabindex="-1"><template v-if="!creating"><div :inert="busy||undefined"><ProductContentEditor ref="contentEditor" :key="contentKey" :product-id="id" :initial-content="contentInitial" :category-type="category?.specificationType" :disabled="busy" @state="contentState=$event" @saved="contentSaved"/></div></template><template v-else><h2>Mô tả và thông số</h2><p class="bm-seller-help">Tạo bản nháp để soạn mô tả và khai báo thông số theo danh mục.</p></template></section>
   <section id="bm-seller-gallery" class="bm-seller-editor-section" tabindex="-1"><SellerGalleryManager v-if="!creating" ref="galleryManager" :product-id="id" :name="product.name" @updated="gallery=$event" @state="galleryState=$event"/><template v-else><h2>Hình ảnh sản phẩm</h2><p class="bm-seller-help">Thêm tối đa 8 ảnh sau khi có mã sản phẩm. Hỗ trợ chọn nhiều ảnh và kéo thả.</p></template></section>
   <section id="bm-seller-stock" class="bm-seller-editor-section" tabindex="-1"><h2>Tồn kho và vận chuyển</h2><template v-if="stock"><p>Tồn khả dụng: <strong>{{ stock.stock }}</strong> · {{ stock.stock===0?'Hết hàng':'Còn hàng' }}</p><InventoryEditor :product="stock" :disabled="locked" @updated="stockUpdated" @editing="stockEditing=$event" @saving="stockSaving=$event"/></template><p v-else class="bm-seller-help">Tồn ban đầu được lưu cùng bản nháp ở phần thông tin cơ bản.</p><div class="bm-seller-shipping-note"><MarketIcon name="truck"/><div><h3>Kiện hàng đã đóng gói</h3><p>Cấu hình khối lượng và dài × rộng × cao trong mẫu kiện của gian hàng, cho đúng bộ sản phẩm và số lượng. Số đo cây hoặc chậu không thay thế số đo kiện.</p><RouterLink :to="{path:'/seller/store',hash:'#seller-shipping'}">Quản lý mẫu kiện vận chuyển</RouterLink></div></div></section>
   <section id="bm-seller-review" class="bm-seller-editor-section" tabindex="-1"><h2>Xem trước và gửi duyệt</h2><template v-if="!creating"><p v-if="product.status==='PENDING'">Sản phẩm đang chờ quản trị viên xem xét. Kết quả sẽ được cập nhật tại đây; chưa có thời hạn duyệt được cam kết.</p><p v-else-if="product.status==='REJECTED'">Kiểm tra lý do từ chối bên dưới, chỉnh sửa và lưu trước khi gửi lại.</p><p v-else>Kiểm tra nội dung đã lưu và danh sách cần hoàn thiện trước khi gửi. Máy chủ sẽ kiểm tra lại quyền sở hữu, gian hàng và danh mục đang hoạt động.</p><ul class="bm-seller-review-missing"><li v-for="item in requirements.filter(r=>!r.met)" :key="item.key"><a :href="'#'+item.target" @click.prevent="jump(item.target)">{{ item.label }}</a></li></ul><p v-if="dirty||galleryState.draft||stockEditing" role="status">Hoàn tất lưu các trường, tồn kho và hàng đợi ảnh trước khi gửi duyệt.</p><div class="bm-seller-editor-actions"><button type="button" class="button button-outline" :disabled="locked||dirty||!gallery" @click="openPreview">Xem trước như khách hàng</button><button type="button" class="button button-primary" :disabled="!canSubmit" @click="submit">{{ product.status==='REJECTED'?'Gửi duyệt lại':'Gửi duyệt sản phẩm' }}</button></div><details class="bm-seller-history" open><summary>Lịch sử xét duyệt gần nhất</summary><p v-if="historyError" role="alert">{{ historyError }} <button class="button button-outline" @click="loadHistory">Thử tải lại</button></p><ol v-else-if="history.length"><li v-for="(item,index) in history" :key="index"><strong>{{ moderationLabels[item.action]||'Cập nhật xét duyệt' }}</strong><time :datetime="item.createdAt">{{ time(item.createdAt) }}</time><p>{{ item.reason }}</p></li></ol><p v-else class="bm-seller-help">Chưa có lịch sử gửi hoặc xét duyệt được ghi nhận.</p></details></template><p v-else class="bm-seller-help">Hoàn thiện bản nháp rồi xem trước và gửi duyệt tại đây.</p></section>
  </div><aside class="bm-seller-checklist"><h2>Cần hoàn thiện</h2><p>Kiểm tra dữ liệu đã lưu</p><ul><li v-for="item in requirements" :key="item.key"><MarketIcon :name="item.met?'check':'clock'"/><a :href="'#'+item.target" @click.prevent="jump(item.target)">{{ item.label }}<small>{{ item.met?'Đã có':'Cần bổ sung' }}</small></a></li></ul><p class="bm-seller-help">Thông số tùy chọn chỉ điền khi có thông tin thực tế. Không có điểm hoàn thành hoặc dữ liệu tự điền.</p></aside></div></template>
  <SellerProductPreview v-if="!creating&&loaded" ref="preview" :product="product" :content="content" :gallery="gallery" :category="category?.name"/>
 </div></SellerLayout>
</template>
<script setup>
import {ref,watch} from 'vue';import SellerLayout from '../../pages/Marketplace/Seller/SellerLayout.vue';import MarketIcon from '../marketplace/MarketIcon.vue';import ProductContentEditor from '../marketplace/ProductContentEditor.vue';import SellerGalleryManager from '../marketplace/SellerGalleryManager.vue';import InventoryEditor from '../marketplace/InventoryEditor.vue';import SellerProductPreview from './SellerProductPreview.vue';import {useSellerProductEditor} from '../../composables/useSellerProductEditor.js';import {productStatusLabels} from '../../services/sellerProduct.js';import '../../css/seller-product-editor.css';
const {id,creating,form,product,categories,content,gallery,stock,history,loading,loaded,busy,error,success,fields,conflict,historyError,lastSaved,contentEditor,basicForm,errorSummary,preview,galleryManager,contentState,galleryState,stockEditing,stockSaving,basicDirty,dirty,locked,category,back,requirements,canSubmit,save,submit,reload,loadHistory,contentSaved,stockUpdated,jump,openPreview}=useSellerProductEditor();
// Snapshot is only replaced on explicit whole-product reload, never on a child's save.
const contentInitial=ref(null),contentKey=ref(0);watch(loaded,value=>{if(value){contentInitial.value=content.value;contentKey.value++;}},{flush:'sync'});
const fieldTarget=key=>({categoryId:'category',stock:creating?'stock-initial':'stock'}[key]||key);
const sections=[{id:'bm-seller-basic',label:'Thông tin cơ bản'},{id:'bm-seller-content',label:'Mô tả và thông số'},{id:'bm-seller-gallery',label:'Hình ảnh'},{id:'bm-seller-stock',label:'Tồn kho và vận chuyển'},{id:'bm-seller-review',label:'Xem trước và gửi duyệt'}];
const selectedSection=ref(sections[0].id);
const moderationLabels={PRODUCT_SUBMIT:'Đã gửi duyệt',PRODUCT_APPROVE:'Đã duyệt',PRODUCT_REJECT:'Từ chối duyệt',PRODUCT_HIDE:'Đã ẩn',PRODUCT_RESTORE:'Đã khôi phục',PRODUCT_REMOVE:'Đã gỡ'};
const time=value=>new Date(value).toLocaleString('vi-VN',{hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit',year:'numeric'});
</script>
